package com.nigson.experience.consent;
import java.util.*;
import org.junit.jupiter.api.Test;
import com.nigson.shared.events.EventCodec;
import static org.assertj.core.api.Assertions.*;
class PhoneSecretsTest {
 private byte[] key(int value){byte[] out=new byte[32];Arrays.fill(out,(byte)value);return out;}
 @Test void contextualEncryptionRotatesWithoutCrossRecordOrPurposeDecryption(){var old=new PhoneSecrets(1,key(1),"old",Map.of("old",key(2)));UUID id=UUID.randomUUID();byte[] encrypted=old.encrypt(id,"ADDRESS","+2348000000001");var rotated=new PhoneSecrets(1,key(1),"new",Map.of("new",key(3),"old",key(2)));assertThat(rotated.decrypt(id,"ADDRESS",encrypted)).isEqualTo("+2348000000001");assertThat(encrypted).isNotEqualTo(old.encrypt(id,"ADDRESS","+2348000000001"));assertThatThrownBy(()->rotated.decrypt(UUID.randomUUID(),"ADDRESS",encrypted)).isInstanceOf(IllegalArgumentException.class);assertThatThrownBy(()->rotated.decrypt(id,"PROOF",encrypted)).isInstanceOf(IllegalArgumentException.class);encrypted[encrypted.length-2]^=1;assertThatThrownBy(()->rotated.decrypt(id,"ADDRESS",encrypted)).isInstanceOf(IllegalArgumentException.class);}
 @Test void hashesAndProofsAreKeyedAndBoundToVerification(){var first=new PhoneSecrets(1,key(1),"one",Map.of("one",key(2)));var other=new PhoneSecrets(1,key(3),"one",Map.of("one",key(2)));String hash=first.fingerprint("+2348000000001");assertThat(hash).hasSize(64).isNotEqualTo(other.fingerprint("+2348000000001"));UUID proof=UUID.randomUUID();String saved=first.proof(proof,hash,"000001");assertThat(first.matches(proof,hash,"000001",saved)).isTrue();assertThat(first.matches(proof,hash,"000002",saved)).isFalse();assertThat(first.matches(UUID.randomUUID(),hash,"000001",saved)).isFalse();for(int n=0;n<100;n++)assertThat(first.code()).matches("[0-9]{6}");assertThat(first.toString()).isEqualTo("PhoneSecrets[protected]");}
 @Test void closedOptInRequiresExplicitNigeriaPhoneChannelAndPurpose(){assertThatThrownBy(()->PhoneValues.input(EventCodec.JSON.readTree("{\"channel\":\"SMS\",\"address\":\"08000000001\",\"policyVersion\":\"synthetic\",\"consentedPurposes\":[\"MARKETING\"]}"))).isInstanceOf(RuntimeException.class);assertThatThrownBy(()->new PhoneValues.Input("SMS","+2348000000001","synthetic",Set.of())).isInstanceOf(RuntimeException.class);assertThatThrownBy(()->new PhoneValues.Input("SMS","+2348000000001","synthetic",Set.of("NEWSLETTER"))).isInstanceOf(RuntimeException.class);var value=new PhoneValues.Input("WHATSAPP","+2348000000001","synthetic",Set.of("ORDER_UPDATES"));assertThat(value.toString()).doesNotContain("234","ORDER_UPDATES");}
}
